arguments.argument:
// 数値をキーボードから入力指定

switch show_menu("
Set Flag - Play Voice when Farting ("+bool2string(play_with_effect)+")
|Set Flag - Change Voice Pitch Randomly ("+bool2string(global.voice_pitch)+")"
  ,-1) {
  case 0: // interval max
    play_with_effect = !play_with_effect;
    if( play_with_effect )
        draw_text_on_board("Play Voice when Farting", true);
    else
        draw_text_on_board("Not Play Voice with Farting", true);
  break;
  case 1: 
    global.voice_pitch = !global.voice_pitch;
    if( global.voice_pitch )
        draw_text_on_board("Voice Pitch changes randomly", true);
    else
        draw_text_on_board("Voice Pitch doesnt change", true);
  break;
 
  default:
  break;
  
}
